      this.btn_menuright.Visible = true;
      MarbleTempVars.DockRightEnable = false;
      if (!MarbleTempVars.DockRightEnable)
        this.pnl_down.Width = 1910;
      else
        this.pnl_down.Width = 1575;
      clsAppMarbleItems.frmBottomPanelV1.pnl_base.Width = this.pnl_down.Width - 2;
      this.btn_menudown.Left = 840;
