      this.btn_menuup.Visible = false;
      MarbleTempVars.DockBottomEnable = true;
    }
    if (!(control.Name == this.btn_menudown.Name))
      return;
    this.pnl_down.Visible = false;
    this.pnl_down.Height = 1;
    this.pnl_down.Left = 0;
    this.pnl_maincmd.Height = 985;
    this.pnl_down.Top = this.pnl_maincmd.Height + this.pnl_maincmd.Top - 5;
    this.btn_menuup.Visible = true;
    clsAppMarbleItems.frmBottomPanelV1.MenuButtonColors(clsAppMarbleItems.frmBottomPanelV1.buTab_Main.SelectedIndex);
    MarbleTempVars.DockBottomEnable = false;
  }

